import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { globalErrorToast, globalSuccessToast } from "@/lib/toast";
import { trpc } from "@/utils/trpc";
import { useQuery } from "@tanstack/react-query";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { pageHead } from "@/utils/page-head";
import { ArrowLeft, CheckCircle2, Loader2, Info, XCircle } from "lucide-react";
import { useEffect, useState } from "react";
import z from "zod";
import { Separator } from "@/components/ui/separator";
import ImageWithFallback from "@/components/image-with-fallback";
import { Alert, AlertTitle, AlertDescription } from "@/components/ui/alert";

const validateEmailSchema = z.object({
  email: z.string().optional(),
});

export const Route = createFileRoute("/(auth)/verify-email")({
  validateSearch: validateEmailSchema,
  component: VerifyEmailComponent,
  head: () => pageHead("Verifikasi Email"),
});

const BannerImage = "/assets/banner-auth.webp";

function VerifyEmailComponent() {
  const { email: emailFromSearch } = Route.useSearch();
  const [emailInput, setEmailInput] = useState<string>("");
  const [email, setEmail] = useState<string>("");
  const navigate = useNavigate();

  // Set email from search param on load
  useEffect(() => {
    if (emailFromSearch) {
      setEmail(emailFromSearch);
      setEmailInput(emailFromSearch);
    }
  }, [emailFromSearch]);

  const {
    data: verificationStatusData,
    isLoading,
    error,
  } = useQuery({
    ...trpc.platform.auth.getVerificationStatus.queryOptions({ email }),
    enabled: !!email,
    refetchInterval: (query) => {
      return query.state.data?.verificationStatus === "pending" ? 3000 : false;
    },
  });

  // Watch for approval status
  useEffect(() => {
    if (verificationStatusData?.verificationStatus === "approved") {
      globalSuccessToast("Akun Anda telah disetujui oleh Administrator!");
      const timer = setTimeout(() => {
        navigate({ to: "/login" });
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [verificationStatusData?.verificationStatus, navigate]);

  const handleCheckStatus = (): void => {
    const res = z.string().email().safeParse(emailInput);
    if (!res.success) {
      globalErrorToast("Tolong masukkan email yang valid.");
      return;
    }
    setEmail(emailInput);
  };

  const handleBackToEmail = (): void => {
    setEmail("");
    setEmailInput("");
    navigate({
      to: "/verify-email",
      search: { email: undefined },
    });
  };

  const handleBack = (): void => {
    navigate({ to: "/register" });
  };

  const renderHeader = () => {
    if (!email) {
      return (
        <div className="flex flex-col gap-1 text-center md:text-left">
          <h1 className="font-['Poppins'] text-[32px] leading-12 font-semibold text-[#242321]">
            Status Verifikasi
          </h1>
          <p className="font-['Poppins'] text-[14px] leading-5.25 font-medium text-[#242321]">
            Cek pendaftaran akun Anda
          </p>
        </div>
      );
    }

    if (isLoading) {
      return (
        <div className="flex flex-col gap-1 text-center md:text-left">
          <h1 className="font-['Poppins'] text-[32px] leading-12 font-semibold text-[#242321]">
            Memeriksa...
          </h1>
          <p className="font-['Poppins'] text-[14px] leading-5.25 font-medium text-[#242321]">
            Sedang mengambil status akun Anda
          </p>
        </div>
      );
    }

    if (verificationStatusData?.verificationStatus === "approved") {
      return (
        <div className="flex flex-col gap-1 text-center md:text-left">
          <h1 className="font-['Poppins'] text-[32px] leading-12 font-semibold text-[#242321]">
            Berhasil!
          </h1>
          <p className="font-['Poppins'] text-[14px] leading-5.25 font-medium text-[#242321]">
            Akun Anda telah aktif
          </p>
        </div>
      );
    }

    if (verificationStatusData?.verificationStatus === "rejected") {
      return (
        <div className="flex flex-col gap-1 text-center md:text-left">
          <h1 className="font-['Poppins'] text-[32px] leading-12 font-semibold text-[#242321]">
            Ditolak
          </h1>
          <p className="font-['Poppins'] text-[14px] leading-5.25 font-medium text-[#242321]">
            Pendaftaran akun ditolak
          </p>
        </div>
      );
    }

    return (
      <div className="flex flex-col gap-1 text-center md:text-left">
        <h1 className="font-['Poppins'] text-[32px] leading-12 font-semibold text-[#242321]">
          Menunggu Verifikasi
        </h1>
        <p className="font-['Poppins'] text-[14px] leading-5.25 font-medium text-[#242321]">
          Dalam peninjauan Administrator
        </p>
      </div>
    );
  };

  return (
    <div className="grid min-h-svh bg-[#F4F4F4] font-['Inter'] lg:grid-cols-2">
      <div className="relative hidden overflow-hidden bg-[#F4F4F4] lg:block">
        <ImageWithFallback
          src={BannerImage}
          alt="Banner"
          className="absolute inset-0 h-full w-full object-cover object-center"
        />
        <div className="pointer-events-none absolute inset-0 bg-linear-to-r from-transparent to-[#F4F4F4]/20" />
      </div>

      <div className="bg-grid-pattern relative flex min-h-svh flex-col items-center justify-center gap-4 border-l border-slate-200/50 bg-[#F4F4F4] p-6 md:p-10 lg:min-h-0">
        <div className="flex w-full max-w-100 flex-col gap-6">
          {renderHeader()}

          <Card className="rounded-lg border-slate-200 bg-white shadow-sm">
            {/* Input Email Screen */}
            {!email && (
              <>
                <CardHeader className="space-y-1 px-6 pt-6 pb-6">
                  <CardTitle className="font-['Poppins'] text-[20px] leading-6 font-semibold text-[#4D4D4D]">
                    Cek Status Pendaftaran
                  </CardTitle>
                  <CardDescription className="font-['Poppins'] text-[14px] leading-5.25 font-normal text-[#64748B]">
                    Masukkan email Anda untuk melihat status verifikasi akun
                    oleh Administrator.
                  </CardDescription>
                </CardHeader>

                <CardContent className="space-y-5 px-6 pb-6">
                  <div className="space-y-1.5">
                    <label
                      htmlFor="email"
                      className="font-['Poppins'] text-[16px] font-medium text-[#4D4D4D]"
                    >
                      Email
                    </label>
                    <Input
                      id="email"
                      type="email"
                      placeholder="contoh@email.com"
                      value={emailInput}
                      onChange={(e) => setEmailInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") handleCheckStatus();
                      }}
                      className="h-9 rounded-lg border-slate-200 font-['Poppins'] text-[14px] focus-visible:ring-[#1061D6] focus-visible:ring-offset-0"
                    />
                  </div>

                  <Button
                    onClick={handleCheckStatus}
                    disabled={!emailInput}
                    className="h-9 w-full rounded-lg bg-[#1061D6] font-['Poppins'] text-[16px] font-semibold text-[#F8FAFC] hover:bg-blue-700"
                  >
                    Cek Status
                  </Button>

                  <div className="flex flex-col gap-3 pt-2">
                    <Separator className="bg-slate-100" />
                    <div className="text-center">
                      <Button
                        variant="link"
                        className="h-auto p-0 font-['Poppins'] text-sm text-[#64748B] no-underline hover:text-[#1061D6] hover:underline"
                        onClick={handleBack}
                      >
                        <ArrowLeft className="mr-2 h-4 w-4" />
                        Kembali ke Halaman Daftar
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </>
            )}

            {/* Loading Status */}
            {email && isLoading && (
              <CardContent className="flex flex-col items-center gap-6 pt-10 pb-10 text-center">
                <Loader2 className="h-10 w-10 animate-spin text-[#1061D6]" />
                <p className="font-['Poppins'] text-[14px] text-[#64748B]">
                  Mengambil status pendaftaran akun...
                </p>
              </CardContent>
            )}

            {/* Error or Not Found Screen */}
            {email && !isLoading && error && (
              <CardContent className="flex flex-col items-center gap-6 pt-10 pb-10 text-center">
                <div className="rounded-full bg-red-50 p-4">
                  <XCircle className="h-14 w-14 text-red-600" />
                </div>
                <div className="space-y-2">
                  <h2 className="font-['Poppins'] text-[20px] font-semibold text-[#4D4D4D]">
                    Email Tidak Terdaftar
                  </h2>
                  <p className="font-['Poppins'] text-[14px] text-[#64748B]">
                    Alamat email{" "}
                    <span className="font-semibold text-[#4D4D4D]">
                      {email}
                    </span>{" "}
                    tidak terdaftar di sistem kami.
                  </p>
                </div>
                <div className="flex w-full flex-col gap-2">
                  <Button
                    onClick={handleBackToEmail}
                    className="h-10 w-full rounded-lg bg-[#1061D6] font-['Poppins'] text-[16px] font-semibold text-[#F8FAFC] hover:bg-blue-700"
                  >
                    Ganti Alamat Email
                  </Button>
                  <Button
                    variant="ghost"
                    onClick={() => navigate({ to: "/register" })}
                    className="h-10 w-full font-['Poppins'] text-sm text-[#64748B]"
                  >
                    Daftar Akun Baru
                  </Button>
                </div>
              </CardContent>
            )}

            {/* Approved Screen */}
            {email &&
              !isLoading &&
              !error &&
              verificationStatusData?.verificationStatus === "approved" && (
                <CardContent className="flex flex-col items-center gap-6 pt-10 pb-10 text-center">
                  <div className="rounded-full bg-green-50 p-4">
                    <CheckCircle2 className="h-14 w-14 text-green-600" />
                  </div>
                  <div className="space-y-2">
                    <h2 className="font-['Poppins'] text-[20px] font-semibold text-[#4D4D4D]">
                      Pendaftaran Disetujui!
                    </h2>
                    <p className="font-['Poppins'] text-[14px] text-[#64748B]">
                      Akun Anda telah disetujui oleh Administrator. Mengalihkan
                      ke halaman masuk...
                    </p>
                  </div>
                  <Loader2 className="h-8 w-8 animate-spin text-[#1061D6]" />
                </CardContent>
              )}

            {/* Pending Screen */}
            {email &&
              !isLoading &&
              !error &&
              verificationStatusData?.verificationStatus === "pending" && (
                <>
                  <CardHeader className="space-y-1 px-6 pt-6 pb-6">
                    <CardTitle className="font-['Poppins'] text-[20px] leading-6 font-semibold text-[#4D4D4D]">
                      Menunggu Persetujuan
                    </CardTitle>
                    <CardDescription className="font-['Poppins'] text-[14px] leading-5.25 font-normal text-[#64748B]">
                      Status akun dengan email{" "}
                      <span className="font-semibold text-[#4D4D4D]">
                        {email}
                      </span>
                    </CardDescription>
                  </CardHeader>

                  <CardContent className="space-y-6 px-6 pb-6">
                    <Alert className="border-blue-200 bg-blue-50 text-blue-800">
                      <Info className="h-4 w-4 text-blue-600" />
                      <AlertTitle className="font-semibold text-blue-900">
                        Menunggu Verifikasi Administrator
                      </AlertTitle>
                      <AlertDescription className="text-blue-700">
                        Pendaftaran akun Anda sedang dalam antrean verifikasi.
                        Mohon tunggu beberapa saat. Halaman ini akan mendeteksi
                        persetujuan secara otomatis.
                      </AlertDescription>
                    </Alert>

                    <div className="flex flex-col items-center justify-center py-4">
                      <Loader2 className="h-10 w-10 animate-spin text-[#1061D6]" />
                    </div>

                    <div className="flex flex-col gap-3">
                      <Separator className="bg-slate-100" />
                      <Button
                        onClick={handleBackToEmail}
                        variant="outline"
                        className="h-10 w-full rounded-lg font-['Poppins'] text-[14px] text-[#64748B] hover:text-[#4D4D4D]"
                      >
                        Periksa Email Lain
                      </Button>
                      <Button
                        variant="ghost"
                        onClick={() => navigate({ to: "/login" })}
                        className="h-10 w-full font-['Poppins'] text-sm text-[#64748B]"
                      >
                        Kembali ke Halaman Masuk
                      </Button>
                    </div>
                  </CardContent>
                </>
              )}

            {/* Rejected Screen */}
            {email &&
              !isLoading &&
              !error &&
              verificationStatusData?.verificationStatus === "rejected" && (
                <>
                  <CardHeader className="space-y-1 px-6 pt-6 pb-6">
                    <CardTitle className="font-['Poppins'] text-[20px] leading-6 font-semibold text-[#4D4D4D]">
                      Pendaftaran Ditolak
                    </CardTitle>
                    <CardDescription className="font-['Poppins'] text-[14px] leading-5.25 font-normal text-[#64748B]">
                      Status akun dengan email{" "}
                      <span className="font-semibold text-[#4D4D4D]">
                        {email}
                      </span>
                    </CardDescription>
                  </CardHeader>

                  <CardContent className="space-y-6 px-6 pb-6">
                    <Alert
                      variant="destructive"
                      className="border-red-200 bg-red-50 text-red-800"
                    >
                      <XCircle className="h-4 w-4 text-red-600" />
                      <AlertTitle className="font-semibold text-red-900">
                        Pendaftaran Ditolak
                      </AlertTitle>
                      <AlertDescription className="text-red-700">
                        Pendaftaran akun Anda ditolak oleh Administrator. <br />
                        <span className="font-semibold">Alasan:</span>{" "}
                        {verificationStatusData.verificationRejectionReason ??
                          "Tidak ada alasan spesifik."}
                      </AlertDescription>
                    </Alert>

                    <div className="flex flex-col gap-3">
                      <Separator className="bg-slate-100" />
                      <Button
                        className="h-10 w-full rounded-lg bg-red-600 font-semibold text-white hover:bg-red-700"
                        onClick={() => {
                          navigate({
                            to: "/register",
                            search: {
                              name: verificationStatusData.name ?? "",
                              email: verificationStatusData.email ?? "",
                              phone: verificationStatusData.phone ?? "",
                              address: verificationStatusData.address ?? "",
                            },
                          });
                        }}
                      >
                        Daftar Kembali
                      </Button>
                      <Button
                        onClick={handleBackToEmail}
                        variant="outline"
                        className="h-10 w-full rounded-lg font-['Poppins'] text-[14px] text-[#64748B] hover:text-[#4D4D4D]"
                      >
                        Periksa Email Lain
                      </Button>
                    </div>
                  </CardContent>
                </>
              )}
          </Card>
        </div>
      </div>
    </div>
  );
}
